  const trendV5=(a=68,b=82)=>`<svg class="v5-chart" viewBox="0 0 620 190" preserveAspectRatio="none"><defs><linearGradient id="v5area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#6d28ff"/><stop offset="1" stop-color="#fff"/></linearGradient></defs><line class="grid" x1="35" x2="610" y1="35" y2="35"/><line class="grid" x1="35" x2="610" y1="78" y2="78"/><line class="grid" x1="35" x2="610" y1="121" y2="121"/><line class="grid" x1="35" x2="610" y1="164" y2="164"/><path class="warning" d="M40 82L610 82"/><path class="area" d="M40 142 C100 132 126 119 176 124 S252 101 308 106 S390 84 448 90 S544 58 608 64 L608 165 L40 165Z"/><path class="line" d="M40 142 C100 132 126 119 176 124 S252 101 308 106 S390 84 448 90 S544 58 608 64"/><path class="line2" d="M40 151 C96 143 128 137 176 139 S252 126 308 128 S394 111 448 114 S548 96 608 99"/><text x="40" y="183">Jan</text><text x="130" y="183">Feb</text><text x="220" y="183">Mar</text><text x="310" y="183">Apr</text><text x="400" y="183">May</text><text x="490" y="183">Jun</text><text x="580" y="183">Jul</text><text x="42" y="135">${a}%</text><text x="608" y="57" text-anchor="end">${b}%</text></svg>`;
  const sparkV5=(tone='brand')=>`<svg class="sparkline-v5" viewBox="0 0 110 28" preserveAspectRatio="none"><path class="base" d="M2 23H108"/><path style="stroke:${tone==='green'?'var(--emerald)':tone==='red'?'var(--red)':tone==='amber'?'var(--amber)':'var(--brand)'}" d="M2 22 C18 20 20 13 34 16 S51 7 64 12 S80 5 108 6"/></svg>`;
