 function kpiWizardPageV6(){
   const s=state.v6WizardStep||1;
   const names=[['Definition','Define KPI details'],['Calculation','Define how it is calculated'],['Data source','Select approved data'],['Targets & thresholds','Set target bands'],['Ownership','Assign owners'],['Review','Confirm & submit']];
   const body=s===1?`<div class="form-grid-v6"><div class="field-v6"><label>KPI name *</label><input value="Revenue Growth Rate"></div><div class="field-v6"><label>Code *</label><input value="FIN-REV-001"></div><div class="field-v6 full"><label>Description *</label><textarea>Measures the percentage increase in recurring revenue compared with the same period in the previous year.</textarea></div><div class="field-v6"><label>Category *</label><select><option>Financial</option></select></div><div class="field-v6"><label>Type *</label><select><option>Percentage</option></select></div><div class="field-v6"><label>Frequency *</label><select><option>Monthly</option></select></div><div class="field-v6"><label>Direction *</label><select><option>Higher is better</option></select></div><div class="field-v6"><label>Scope *</label><select><option>Organisation</option></select></div><div class="field-v6"><label>BSC perspective *</label><select><option>Financial</option></select></div><div class="field-v6"><label>Linked objective</label><select><option>Drive sustainable revenue growth</option></select></div><div class="field-v6"><label>Tags</label><div class="tag-row-v6"><span class="tag-v6">Revenue</span><span class="tag-v6">Growth</span><span class="tag-v6">Recurring</span></div></div></div>`:s===2?`<div class="form-grid-v6"><div class="field-v6"><label>Calculation method *</label><select><option>% Change</option></select></div><div class="field-v6"><label>Aggregation *</label><select><option>Period end</option></select></div><div class="field-v6 full"><label>Formula</label><textarea>((Current period revenue - Prior period revenue) / Prior period revenue) × 100</textarea></div><div class="field-v6"><label>Rounding</label><select><option>2 decimals</option></select></div><div class="field-v6"><label>Null handling</label><select><option>Flag as missing</option></select></div></div>`:s===3?`<div class="form-grid-v6"><div class="field-v6"><label>Source module *</label><select><option>Accounting / ERP</option></select></div><div class="field-v6"><label>Source field *</label><input value="TotalRevenue"></div><div class="field-v6"><label>Refresh frequency</label><select><option>Daily at 02:00</option></select></div><div class="field-v6"><label>Approval required</label><select><option>Yes - high impact metric</option></select></div><div class="field-v6 full"><label>Transformation</label><textarea>Aggregate approved recurring revenue categories and compare to prior period.</textarea></div></div>`:s===4?`<div class="form-grid-v6"><div class="field-v6"><label>Target *</label><input value="10.0%"></div><div class="field-v6"><label>Stretch target</label><input value="15.0%"></div><div class="field-v6"><label>Red threshold</label><input value="< 5.0%"></div><div class="field-v6"><label>Amber threshold</label><input value="5.0% – 9.9%"></div><div class="field-v6"><label>Green threshold</label><input value="≥ 10.0%"></div><div class="field-v6"><label>Benchmark</label><input value="12.5%"></div></div>`:s===5?`<div class="form-grid-v6"><div class="field-v6"><label>KPI owner</label><div>${personV5('Tendai Nyathi','Finance Manager')}</div></div><div class="field-v6"><label>Data steward</label><div>${personV5('Farai Muchengezi','Performance Office')}</div></div><div class="field-v6"><label>Approver</label><div>${personV5('Tawanda Chikore','Executive Sponsor')}</div></div><div class="field-v6"><label>Backup owner</label><div>${personV5('Nyasha Moyo','Business Partner')}</div></div></div>`:`<div class="side-list">${sideItem('Definition','Revenue Growth Rate · FIN-REV-001','Complete','green')}${sideItem('Calculation','% Change · period end','Complete','green')}${sideItem('Data source','Accounting / ERP · TotalRevenue','Validated','green')}${sideItem('Thresholds','Target 10% · stretch 15%','Complete','green')}${sideItem('Ownership','Finance Manager + Executive Sponsor','Complete','green')}${sideItem('Governance','2-level approval before activation','Ready','green')}</div>`;
   return `<div class="page layer-v6"><div class="layer-breadcrumb-v6">${backV6('KPI Management','objectives')}<span>›</span><span>Create KPI</span></div>${pageHead('Governed KPI setup','Create KPI','A guided workflow for definition, ownership, targets, thresholds, evidence and approval.',btn('Save draft','toast-generic','','file')+btn('Cancel','v6-back','','x')+btn(s===6?'Submit for approval':'Continue','v6-wizard-next','primary','check'))}<div class="steps-v6">${names.map((x,i)=>`<div class="step-v6 ${s===i+1?'active':''}" data-v6-step="${i+1}"><div><i>${i+1}</i><strong>${x[0]}</strong></div><span>${x[1]}</span></div>`).join('')}</div><div class="detail-grid-v6"><div class="detail-main-v6">${panel6(names[s-1][0],names[s-1][1],body,badge(s===6?'Ready for approval':'Draft'))}<div class="layer-toolbar-v6"><button class="btn" data-v6-wizard-prev="1" ${s===1?'disabled':''}>Previous</button><span class="spacer"></span><button class="btn primary" data-v6-wizard-next="1">${s===6?'Submit for approval':'Next: '+names[Math.min(5,s)][0]}</button></div></div><aside class="detail-aside-v6">${panel6('Live preview','See how the KPI will appear',`<div class="metric-v6" style="--tone:#6517ff"><span>Revenue Growth Rate</span><strong>12.4%</strong><small>Target 10.0% · Monthly</small><div style="margin-top:8px">${badge('On Track')}</div></div>`)}${panel6('Setup guidance','Governance completion',`<div class="side-list">${names.map((x,i)=>sideItem(`${i+1}. ${x[0]}`,i+1<s?'Complete':i+1===s?'In progress':'Pending',i+1<s?'✓':i+1===s?'●':'○',i+1<s?'green':i+1===s?'amber':'')).join('')}</div>`)}${panel6('Governance','Accountability for this KPI',`<div class="side-list">${sideItem('Approval required','Yes','Level 2','amber')}${sideItem('Proposed approver','Tendai Nyathi',personV5('Tendai Nyathi'),'')}${sideItem('Data steward','Farai Muchengezi',personV5('Farai Muchengezi'),'')}</div>`)}${panel6('Draft details','Audit metadata',`<div class="side-list">${sideItem('Created by','Adm. User','08 Aug 2026','')}${sideItem('Draft version','0.6','Autosaved','green')}${sideItem('Validation','8 of 8 checks','Passed','green')}</div>`)}</aside></div></div>`;
 }

