(() => {
  const enforceMinTextV7=()=>{
    rootEl.querySelectorAll('*').forEach(el=>{
      if(el instanceof SVGElement && el.tagName.toLowerCase()!=='text') return;
      const fs=parseFloat(getComputedStyle(el).fontSize||'0');
      if(fs>0 && fs<10) el.style.setProperty('font-size','10px','important');
    });
  };
  const oldRender=render;
  render=function(){oldRender();requestAnimationFrame(enforceMinTextV7)};
  const oldOpenDrawer=openDrawer;
  openDrawer=function(...args){oldOpenDrawer(...args);requestAnimationFrame(enforceMinTextV7)};
  const oldModal=modal;
  modal=function(...args){oldModal(...args);requestAnimationFrame(enforceMinTextV7)};
  enforceMinTextV7();
  setTimeout(enforceMinTextV7,120);
  let minTextQueuedV7=false;
  const minTextObserverV7=new MutationObserver(()=>{
    if(minTextQueuedV7) return;
    minTextQueuedV7=true;
    requestAnimationFrame(()=>{minTextQueuedV7=false;enforceMinTextV7()});
  });
  minTextObserverV7.observe(document.body,{childList:true,subtree:true});
  window.MatanhoPerformanceV7TextFloor=10;
})();

