    {id:'learning',name:'Learning & Growth',icon:'strategy',tone:'#7355e6',soft:'#f7f3ff',soft2:'#efe9ff',weight:20,score:86,status:'On track',points:'17.2 weighted points',summary:'Build the leadership depth, specialist capability and knowledge-sharing habits required for long-term growth.',goal:['Increase leadership leverage and succession readiness.','Turn personal expertise into stronger team capability.'],objective:['Complete targeted development milestones and apply them to live work.','Coach emerging leaders and run practical knowledge-sharing sessions.'],kpis:[['Leadership development plan','80%','100%'],['Succession coverage for key roles','2 roles','2 roles'],['Knowledge-sharing commitments','3 sessions','4 sessions']]}
