function depthbar(){const ctx=pageContext();if(document.querySelector('.sig-depthbar'))return;const head=document.querySelector('.page .page-head');if(!head)return;head.insertAdjacentHTML('afterend',`<div class="sig-depthbar"><div class="sig-depth-id"><i></i><div><strong>Layer 1 · ${escSig(ctx.title)}</strong><span>Operational workspace</span></div></div><button class="sig-depth-btn" data-signature-layer="intelligence">${sigIcon('spark')} Intelligence</button><button class="sig-depth-btn" data-signature-layer="evidence">${sigIcon('shield')} Evidence & controls</button><button class="sig-depth-btn" data-signature-layer="action">${sigIcon('bolt')} Decisions & actions</button><button class="sig-depth-btn primary" data-signature-layer="intelligence">${sigIcon('layers')} Explore deeper</button></div>`)}
