function depthNodes(){const bar=document.querySelector('.sig-depthbar');if(!bar||bar.querySelector('.v10-layer-node'))return;const pri=bar.querySelector('.sig-depth-btn.primary');const html='<span class="v10-layer-node current"><b>1</b>Workspace</span><span class="v10-layer-node"><b>2</b>Intelligence</span><span class="v10-layer-node"><b>3</b>Evidence</span><span class="v10-layer-node"><b>4</b>Decisions</span><button class="v10-layer-node" data-v10-room><b>5</b>Scenario</button>';(pri||bar.lastElementChild)?.insertAdjacentHTML('beforebegin',html)}
function hero(){const cfg=current(),p=document.querySelector('#workspace .page');if(!cfg||!p||p.querySelector('.v10-hero'))return;const bar=p.querySelector('.sig-depthbar');if(!bar)return;const [a1,a2]=cfg.a,[b1,b2]=cfg.b;bar.insertAdjacentHTML('afterend',`<section class="v10-hero"><div class="v10-hero-main"><span class="v10-hero-kicker">Live executive signal · ${esc10(state?.entity||'Matanho Capital')}</span><div class="v10-hero-title"><div class="v10-hero-score">${esc10(cfg.score)}<small>%</small></div><div class="v10-hero-copy"><h2>${esc10(cfg.title)}</h2><p>${esc10(cfg.copy)}</p></div></div><div class="v10-hero-actions"><button class="primary" data-v10-room>Open Decision Room</button><button data-signature-layer="intelligence">Explore intelligence</button><button data-signature-layer="evidence">Inspect evidence</button></div><div class="v10-hero-signals"><span><i></i>Data current · 8 min</span><span><i></i>Controls validated</span></div></div><div class="v10-hero-side"><article class="v10-hero-card violet"><span>${esc10(a2)}</span><strong>${esc10(a1)}</strong><p>Material movement in the active reporting period.</p><div class="v10-mini-bars"><i></i><i></i><i></i><i></i><i></i></div></article><article class="v10-hero-card blue"><span>${esc10(b2)}</span><strong>${esc10(b1)}</strong><p>Decision support based on governed evidence and current workflow state.</p><div class="v10-mini-bars"><i></i><i></i><i></i><i></i><i></i></div></article></div></section>`)}
