kpi=function(label,value,sub,ico,trend,page){return `<div class="kpi v11-kpi" data-page="${page}" data-trend="${trend}"><span class="v11-kpi-label">${esc11(label)}</span><div class="v11-kpi-main"><strong>${esc11(value)}</strong><i></i></div><span class="v11-kpi-sub">${esc11(sub)}</span></div>`};
function pulse(){const a=[66,69,71,74,78,82,86],t=[70,72,74,77,80,83,86],f=[66,69,71,74,78,82,88],x=i=>38+i*94,y=v=>244-(v-55)*5.4,pts=v=>v.map((n,i)=>`${x(i)},${y(n)}`).join(' ');return `<div class="v11-strategy-pulse"><svg viewBox="0 0 630 270" preserveAspectRatio="none"><defs><linearGradient id="v11StrategyArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#6048ed" stop-opacity=".18"/><stop offset="1" stop-color="#6048ed" stop-opacity="0"/></linearGradient></defs>${[60,70,80,90].map(v=>`<line class="grid" x1="38" x2="606" y1="${y(v)}" y2="${y(v)}"/><text x="30" y="${y(v)+3}" text-anchor="end">${v}%</text>`).join('')}<polygon class="area" points="38,244 ${pts(a)} 602,244"/><polyline class="target" points="${pts(t)}"/><polyline class="actual" points="${pts(a)}"/><polyline class="forecast" points="${pts(f)}"/>${a.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="3"/><text x="${x(i)}" y="257" text-anchor="middle">${['Feb','Mar','Apr','May','Jun','Jul','Aug'][i]}</text>`).join('')}<text x="602" y="${y(88)-9}" text-anchor="end" fill="#2764ff">Forecast 88%</text></svg></div>`}
