(() => {
  'use strict';
  state.tasksTodayCollapsed = state.tasksTodayCollapsed !== false;
  state.v15StrategyTab = state.v15StrategyTab || 'overview';
  const esc15=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  function loadV14(){try{return JSON.parse(localStorage.getItem('matanho.v14')||'{}')}catch(e){return {strategies:[]}}}
  function saveV14(v){try{localStorage.setItem('matanho.v14',JSON.stringify(v))}catch(e){}}
  function strategies(){const v=loadV14();return Array.isArray(v.strategies)?v.strategies:[]}
  function strategyById(id){return strategies().find(x=>x.id===id)}
  function strategyDoc(s){return `<h1>${esc15(s.title)}</h1><p><strong>Cycle:</strong> ${esc15(s.cycle)} &nbsp; <strong>Effective:</strong> ${esc15(s.effective||'')} – ${esc15(s.end||'')}</p><h2>Strategic intent</h2><p>${esc15(s.intent||'')}</p><h2>Vision</h2><p>${esc15(s.vision||'')}</p><h2>Mission</h2><p>${esc15(s.mission||'')}</p><h2>Strategic themes</h2><ol>${String(s.themes||'').split(';').filter(Boolean).map(x=>`<li>${esc15(x.trim())}</li>`).join('')}</ol><h2>Strategic objectives</h2>${(s.objectives||[]).length?`<table><tr><th>Objective</th><th>Theme</th><th>Owner</th><th>Target</th></tr>${s.objectives.map(o=>`<tr><td>${esc15(o.title)}</td><td>${esc15(o.theme)}</td><td>${esc15(o.owner)}</td><td>${esc15(o.target)}</td></tr>`).join('')}</table>`:'<p>No objectives have been added yet.</p>'}<h2>Governance</h2><p>Framework: ${esc15(s.framework||'Balanced Scorecard')}. Review cadence: ${esc15(s.cadence||'Quarterly formal review')}. Risk appetite: ${esc15(s.risk||'Moderate / controlled growth')}. Approval authority: ${esc15(s.approval||'Board of Directors')}.</p>`}
  function ensureStrategyDocs(){strategies().forEach(s=>{let d=state.docs.find(x=>x.id===s.id);const rec={id:s.id,name:s.title,type:'Company Strategy',folder:'Strategy',version:d?.version||'Draft 1',owner:s.owner,status:s.status||'Draft',updated:'11 Aug 2026',retention:'Active + superseded',audience:'Board / Executive / Leadership',content:strategyDoc(s)};if(d)Object.assign(d,rec);else state.docs.unshift(rec)})}
  ensureStrategyDocs();
  function setStrategy(id,mutator){const v=loadV14();v.strategies=v.strategies||[];const s=v.strategies.find(x=>x.id===id);if(!s)return null;mutator(s);v.activeStrategyId=id;saveV14(v);ensureStrategyDocs();return s}
  function renderStrategyLayer(){const s=strategyById(state.v15StrategyId);if(!s){state.v15StrategyId=null;return ''}const themes=String(s.themes||'').split(';').map(x=>x.trim()).filter(Boolean),objs=s.objectives||[],tab=state.v15StrategyTab||'overview';const tabs=[['overview','Overview'],['themes','Themes & objectives'],['governance','Governance'],['documents','Documents & approvals']];let body='';if(tab==='overview')body=`<div class="v15-strategy-content"><main class="v15-strategy-card"><h3>Strategic narrative</h3><p><strong>Intent.</strong> ${esc15(s.intent||'')}</p><p><strong>Vision.</strong> ${esc15(s.vision||'')}</p><p><strong>Mission.</strong> ${esc15(s.mission||'')}</p><div class="divider"></div><h3>Strategic themes</h3><div class="v15-theme-grid">${themes.map((t,i)=>`<article class="v15-theme"><strong>${String(i+1).padStart(2,'0')} · ${esc15(t)}</strong><span>${['Financial / growth','Stakeholder / market','Internal process','Learning & growth'][i%4]}</span></article>`).join('')}</div></main><aside class="v15-strategy-card"><h3>Decision readiness</h3><div class="v13-side-row"><span>Objectives defined</span><strong>${objs.length}</strong></div><div class="v13-side-row"><span>Scorecard framework</span><strong>${esc15(s.framework||'Balanced Scorecard')}</strong></div><div class="v13-side-row"><span>Review cadence</span><strong>${esc15(s.cadence||'')}</strong></div><div class="v13-side-row"><span>Approval authority</span><strong>${esc15(s.approval||'')}</strong></div><div class="v13-side-row"><span>Status</span><strong>${esc15(s.status||'Draft')}</strong></div></aside></div>`;else if(tab==='themes')body=`<div class="v15-strategy-content"><main class="v15-strategy-card"><div class="v13-toolbar"><div><h3>Strategic objectives</h3><p>Objectives created here belong to this specific strategy cycle and flow into scorecards and performance contracts.</p></div><span class="spacer"></span><button class="btn primary" data-v15-action="strategy-add-objective" data-id="${esc15(s.id)}">${icon('plus')}Add objective</button></div>${objs.length?`<div class="v15-objective-list" style="margin-top:10px">${objs.map((o,i)=>`<article class="v15-objective"><div><strong>${esc15(o.title)}</strong><span>${esc15(o.theme)}</span></div><span>${esc15(o.owner)}</span><span>${esc15(o.target)}</span><button class="btn small" data-v15-action="strategy-remove-objective" data-id="${esc15(s.id+':'+i)}">Remove</button></article>`).join('')}</div>`:`<div class="v15-empty-state" style="margin-top:10px"><strong>No strategic objectives yet</strong>Add the first objective to turn this strategy from a narrative into an executable plan.</div>`}</main><aside class="v15-strategy-card"><h3>Theme register</h3>${themes.map((t,i)=>`<div class="v13-side-row"><span>Theme ${i+1}</span><strong>${esc15(t)}</strong></div>`).join('')}</aside></div>`;else if(tab==='governance')body=`<div class="v15-strategy-content"><main class="v15-strategy-card"><h3>Governance model</h3><div class="v13-side-row"><span>Owner</span><strong>${esc15(s.owner)}</strong></div><div class="v13-side-row"><span>Executive sponsor</span><strong>${esc15(s.sponsor||'Chief Executive Officer')}</strong></div><div class="v13-side-row"><span>Approval authority</span><strong>${esc15(s.approval)}</strong></div><div class="v13-side-row"><span>Risk appetite</span><strong>${esc15(s.risk||'Moderate / controlled growth')}</strong></div><div class="v13-side-row"><span>Review cadence</span><strong>${esc15(s.cadence)}</strong></div></main><aside class="v15-strategy-card"><h3>Review controls</h3><p>Strategy changes are versioned and retained in the controlled document. Objectives and scorecard weights should be reviewed at each formal strategy review.</p><button class="btn" style="width:100%" data-v15-action="strategy-preview" data-id="${esc15(s.id)}">Preview controlled document</button></aside></div>`;else body=`<div class="v15-strategy-content"><main class="v15-strategy-card"><h3>Controlled strategy document</h3><p>The document is generated from this live strategy workspace and stored under the Strategy folder in Document Vault.</p><div class="v13-side-row"><span>Document ID</span><strong>${esc15(s.id)}</strong></div><div class="v13-side-row"><span>Version</span><strong>Draft 1</strong></div><div class="v13-side-row"><span>Status</span><strong>${esc15(s.status||'Draft')}</strong></div><div class="v13-toolbar" style="margin-top:10px"><button class="btn" data-v15-action="strategy-preview" data-id="${esc15(s.id)}">${icon('eye')}Preview document</button><button class="btn" data-page="vault">Open Document Vault</button></div></main><aside class="v15-strategy-card"><h3>Approval workflow</h3><div class="v13-side-row"><span>Prepared by</span><strong>${esc15(s.owner)}</strong></div><div class="v13-side-row"><span>Sponsor review</span><strong>${esc15(s.sponsor||'CEO')}</strong></div><div class="v13-side-row"><span>Final approval</span><strong>${esc15(s.approval)}</strong></div><button class="btn primary" style="width:100%;margin-top:10px" data-v15-action="strategy-submit" data-id="${esc15(s.id)}">Submit for approval</button></aside></div>`;return `<div class="page v15-strategy-page"><div class="v13-breadcrumb"><button data-v15-action="strategy-back">← Company Strategy</button><span>›</span><span>${esc15(s.id)}</span></div><section class="v15-strategy-hero"><div><span class="eyebrow">Layer 2 · Governed strategy workspace</span><h2>${esc15(s.title)}</h2><p>${esc15(s.intent)}</p></div><div class="actions"><button class="btn" data-v15-action="strategy-edit" data-id="${esc15(s.id)}">${icon('edit')}Edit strategy</button><button class="btn" data-v15-action="strategy-preview" data-id="${esc15(s.id)}">${icon('eye')}Preview document</button><button class="btn primary" data-v15-action="strategy-submit" data-id="${esc15(s.id)}">${icon('check')}Submit for approval</button></div></section><div class="v15-strategy-meta">${[['Cycle',s.cycle],['Owner',s.owner],['Sponsor',s.sponsor||'CEO'],['Effective',s.effective||''],['End',s.end||''],['Status',s.status||'Draft']].map(x=>`<div><span>${esc15(x[0])}</span><strong>${esc15(x[1])}</strong></div>`).join('')}</div><div class="v15-strategy-tabs">${tabs.map(t=>`<button class="${tab===t[0]?'active':''}" data-v15-action="strategy-tab" data-id="${t[0]}">${t[1]}</button>`).join('')}</div>${body}</div>`}
  const baseRenderV15=render;
  render=function(){if(state.page==='strategy'&&state.v15StrategyId){renderNav();const w=document.querySelector('#workspace');w.innerHTML=renderStrategyLayer();wireIcons();w.scrollTop=0;return}return baseRenderV15.apply(this,arguments)};
  function editStrategyModal(s){modal('Edit Company Strategy',`${s.id} · controlled strategy workspace`,`<form id="v15EditStrategy" class="v15-strategy-form"><section class="v15-strategy-section"><div class="v15-strategy-grid"><div class="v13-field span2"><label>Strategy title</label><input name="title" value="${esc15(s.title)}"></div><div class="v13-field"><label>Owner</label><input name="owner" value="${esc15(s.owner)}"></div><div class="v13-field"><label>Approval authority</label><input name="approval" value="${esc15(s.approval)}"></div><div class="v13-field full"><label>Strategic intent</label><textarea name="intent">${esc15(s.intent||'')}</textarea></div><div class="v13-field full"><label>Vision</label><textarea name="vision">${esc15(s.vision||'')}</textarea></div><div class="v13-field full"><label>Mission</label><textarea name="mission">${esc15(s.mission||'')}</textarea></div><div class="v13-field full"><label>Strategic themes</label><textarea name="themes">${esc15(s.themes||'')}</textarea></div></div></section></form>`,`<button class="btn" data-action="close-overlays">Cancel</button><button class="btn primary" data-v15-action="strategy-edit-save" data-id="${esc15(s.id)}">Save strategy</button>`,'xl')}
  function addObjectiveModal(s){const themes=String(s.themes||'').split(';').map(x=>x.trim()).filter(Boolean);modal('Add Strategic Objective',`${s.id} · ${s.title}`,`<form id="v15StrategyObjective" class="v15-strategy-grid"><div class="v13-field span2"><label>Objective title</label><input name="title" required placeholder="Define the measurable strategic outcome"></div><div class="v13-field"><label>Theme</label><select name="theme">${themes.map(x=>`<option>${esc15(x)}</option>`).join('')}</select></div><div class="v13-field"><label>Owner</label><select name="owner"><option>Chief Executive Officer</option><option>Chief Financial Officer</option><option>Chief Operating Officer</option><option>Chief People Officer</option></select></div><div class="v13-field"><label>Target</label><input name="target" required placeholder="e.g. 15% growth"></div><div class="v13-field"><label>Review period</label><select name="period"><option>Q1</option><option>Q2</option><option>Q3</option><option>Q4</option><option>Annual</option></select></div></form>`,`<button class="btn" data-action="close-overlays">Cancel</button><button class="btn primary" data-v15-action="strategy-objective-save" data-id="${esc15(s.id)}">Add objective</button>`)}
  document.addEventListener('click',e=>{const a=e.target.closest('[data-v15-action]');if(!a)return;const act=a.dataset.v15Action,id=a.dataset.id||'';e.preventDefault();e.stopImmediatePropagation();if(act==='today-toggle'){state.tasksTodayCollapsed=!state.tasksTodayCollapsed;render()}else if(act==='strategy-open'){__setPm22Page('strategy');state.v15StrategyId=id;state.v15StrategyTab='overview';closeOverlays();render()}else if(act==='strategy-back'){state.v15StrategyId=null;render()}else if(act==='strategy-tab'){state.v15StrategyTab=id;render()}else if(act==='strategy-preview'){ensureStrategyDocs();openDocument(id,false)}else if(act==='strategy-edit'){const s=strategyById(id);if(s)editStrategyModal(s)}else if(act==='strategy-edit-save'){const f=document.getElementById('v15EditStrategy');if(!f)return;const d=new FormData(f);setStrategy(id,s=>Object.assign(s,{title:d.get('title'),owner:d.get('owner'),approval:d.get('approval'),intent:d.get('intent'),vision:d.get('vision'),mission:d.get('mission'),themes:d.get('themes')}));closeOverlays();render();toast('Strategy updated','The workspace and controlled strategy document were updated together.')}else if(act==='strategy-add-objective'){const s=strategyById(id);if(s)addObjectiveModal(s)}else if(act==='strategy-objective-save'){const f=document.getElementById('v15StrategyObjective');if(!f?.reportValidity())return;const d=new FormData(f);setStrategy(id,s=>{s.objectives=s.objectives||[];s.objectives.push({title:d.get('title'),theme:d.get('theme'),owner:d.get('owner'),target:d.get('target'),period:d.get('period'),status:'Draft'})});closeOverlays();render();toast('Strategic objective added','The objective is now part of this strategy cycle and its controlled document.')}else if(act==='strategy-remove-objective'){const [sid,idx]=id.split(':');setStrategy(sid,s=>s.objectives?.splice(Number(idx),1));render()}else if(act==='strategy-submit'){setStrategy(id,s=>s.status='In Review');const d=state.docs.find(x=>x.id===id);if(d)d.status='In Review';render();toast('Strategy submitted','The strategy was routed to the configured approval authority and the document status was updated.')}},true);
  // Stop obsolete generic prototype actions from appearing inside the granular task workspace.
  window.addEventListener('click',e=>{const b=e.target.closest?.('.v13-task-page button');if(!b)return;if(b.dataset.v13Action||b.dataset.v14Action||b.dataset.v15Action)return;if(b.dataset.v12Action==='context-button'||b.dataset.action==='toast-generic'){e.preventDefault();e.stopImmediatePropagation()}},true);
  window.MatanhoV15=Object.freeze({version:'15.0.0',strategies:()=>strategies(),openStrategy:id=>{__setPm22Page('strategy');state.v15StrategyId=id;render()}});
  ensureStrategyDocs();
  render();
})();

