  function noteModal(){const r=currentReview();if(typeof modal!=='function')return;modal('Add Performance Review Note',`${r.name} · ${V.period}`,`<form id="v18NoteForm" class="v18-form-grid"><div class="v18-field"><label>Note type</label><select name="type"><option>Manager observation</option><option>Employee response</option><option>HR / calibration note</option><option>Development follow-up</option></select></div><div class="v18-field"><label>Date</label><input name="date" type="date" value="2026-08-11"></div><div class="v18-field full"><label>Note</label><textarea name="text" required placeholder="Use specific examples, evidence and an actionable next step."></textarea></div><div class="v18-field full"><div class="v18-writing-guide">Write about work and observable behaviour rather than personality. Keep the statement specific, fair, evidence-based and relevant to the agreed objectives.</div></div></form>`,`<button class="btn" data-action="close-overlays">Cancel</button><button class="btn primary" data-v18-action="note-save">Save note</button>`,'xl')}
  function addEvidence(){const r=currentReview(),input=document.createElement('input');input.type='file';input.accept='.pdf,.png,.jpg,.jpeg,.txt,.doc,.docx,.xlsx';input.onchange=()=>{const f=input.files?.[0];if(!f)return;const k=keyFor(r.id,V.period);V.evidence[k]=V.evidence[k]||[];V.evidence[k].unshift({name:f.name,type:f.type||'Document',size:(f.size/1024).toFixed(1)+' KB',date:'11 Aug 2026'});historyAdd(r.id,`Evidence added: ${f.name}`);save();render();if(typeof toast==='function')toast('Evidence recorded',`${f.name} is now linked to ${r.name}'s ${V.period} scorecard.`)};input.click()}
  function saveUpdate(formId='v18UpdateForm'){
    const f=document.getElementById(formId);if(!f?.reportValidity())return;const r=currentReview(),d=new FormData(f),idx=Number(d.get('idx')||0),k=keyFor(r.id,V.period),rows=rowsFor(r),old=rows[idx]||rows[0];V.updates[k]=V.updates[k]||{};V.updates[k][idx]={...(V.updates[k][idx]||{}),actual:String(d.get('actual')||old.actual),target:String(d.get('target')||old.target),score:Number(d.get('score')||old.score),evidence:String(d.get('evidence')||old.evidence),note:String(d.get('note')||''),employeeResponse:String(d.get('employeeResponse')||'')};historyAdd(r.id,`${old.kpi} updated to ${d.get('actual')||old.actual}; review score ${Number(d.get('score')||old.score)}%.`);save();if(typeof closeOverlays==='function')closeOverlays();render();if(typeof toast==='function')toast('Scorecard updated',`${old.kpi} was updated and retained in the scorecard history.`)
  }
  function saveRecord(){const f=document.getElementById('v18RecordForm');if(!f?.reportValidity())return;const r=currentReview(),d=new FormData(f),idx=Number(d.get('idx')||0),rows=rowsFor(r),row=rows[idx]||rows[0],k=keyFor(r.id,V.period);V.updates[k]=V.updates[k]||{};const existing=V.updates[k][idx]||{};V.updates[k][idx]={...existing,actual:String(d.get('actual')||existing.actual||row.actual),score:Number(d.get('score')||existing.score||row.score),target:existing.target||row.target,evidence:String(d.get('evidence')||existing.evidence||row.evidence),note:String(d.get('note')||existing.note||'')};historyAdd(r.id,`${row.kpi} progress update recorded for ${String(d.get('date')||'11 Aug 2026')}.`);save();if(typeof closeOverlays==='function')closeOverlays();render();if(typeof toast==='function')toast('Update recorded',`The ${row.kpi} record and scorecard history were updated.`)}
