  function publish(){const r=currentReview(),prod=reviewProductStatus(r),k=keyFor(r.id,V.period);if(!canManage()){if(typeof toast==='function')toast('Permission required','Publishing is available to managers, HR/M&E, executives and system administrators.');return}if(!['Completed','Calibrated'].includes(r.status)){if(typeof toast==='function')toast('Review not final enough',`This scorecard remains ${prod[0].toLowerCase()}. Complete or calibrate the source performance review before publication.`);return}V.products[k]=V.products[k]||{};V.products[k].publishedAt='11 Aug 2026';V.products[k].publishedBy=state.role;historyAdd(r.id,'Employee scorecard published from the governed performance review.');save();render();if(typeof toast==='function')toast('Scorecard published',`${r.name}'s ${V.period} scorecard was published from the ${r.status.toLowerCase()} review record.`)}
  function preview(){const r=currentReview(),d=reviewDraft(r),rows=rowsFor(r),score=overall(rows),prod=reviewProductStatus(r),k=keyFor(r.id,V.period),notes=V.notes[k]||[],product=V.products[k]||{};const table=rows.map(x=>`<tr><td><strong>${h(x.name)}</strong><br>${h(x.goal[0])}</td><td>${h(x.goal[1])}</td><td><strong>${h(x.kpi)}</strong><br>${h(x.evidence)}</td><td>${h(x.actual)}</td><td>${h(x.target)}</td><td>${x.weight}%</td><td><strong>${Math.round(x.score)}%</strong><br>${h(x.status)}</td></tr>`).join('');const noteText=notes[0]?.text||'No employee response has been recorded in the scorecard workspace.';const body=`<article class="v18-scorecard-paper"><header class="v18-paper-head"><div><span>Matanho Performance Management · Controlled Employee Scorecard</span><h2>${h(r.name)} — ${h(V.period)} Performance Scorecard</h2><p>${h(r.role)} · ${h(r.dept)} · Source review ${h(r.id)}</p></div><div class="v18-paper-score"><strong>${score}%</strong><small>Weighted review outcome</small></div></header><div class="v18-paper-meta"><div><span>Review status</span><strong>${h(r.status)}</strong></div><div><span>Overall rating</span><strong>${h(d.overall||r.rating)}</strong></div><div><span>Scorecard state</span><strong>${h(product.publishedAt?'Published':prod[0])}</strong></div><div><span>Evidence coverage</span><strong>${evidenceCoverage(rows)}%</strong></div><div><span>Period</span><strong>${h(V.period)}</strong></div></div><section class="v18-paper-section"><h3>Performance outcome matrix</h3><div style="overflow:auto"><table class="v18-paper-table"><thead><tr><th>Perspective & objective</th><th>Linked company goal</th><th>KPI & evidence</th><th>Actual</th><th>Target</th><th>Weight</th><th>Review result</th></tr></thead><tbody>${table}</tbody></table></div></section><section class="v18-paper-section"><h3>Manager performance summary</h3><p>${h(d.managerComment)}</p></section><section class="v18-paper-section"><div style="display:grid;grid-template-columns:1fr 1fr;gap:14px"><div><h3>Strengths evidenced</h3><p>${h(d.strengths)}</p></div><div><h3>Development priorities & next action</h3><p>${h(d.development)}</p></div></div></section><section class="v18-paper-section"><h3>Employee response / context</h3><p>${h(noteText)}</p></section><section class="v18-paper-section"><h3>Rating scale and governance</h3><p>The rating reflects performance against agreed expectations using evidence from the review period. Calibration should test consistency across comparable roles. The scorecard records outcomes and agreed next actions; it does not substitute for the performance conversation.</p></section><section class="v18-paper-section"><div class="v18-signoff"><div><span>Employee acknowledgement</span><strong>${r.status==='Completed'?'Requested':'Pending'}</strong></div><div><span>Manager sign-off</span><strong>${r.status==='Completed'||r.status==='Calibrated'?'Recorded / workflow complete':'Pending'}</strong></div><div><span>HR / calibration</span><strong>${r.status==='Calibrated'||r.status==='Completed'?'Validated':'Pending'}</strong></div></div></section></article>`;if(typeof modal==='function')modal(`${r.name} · Scorecard Preview`,`${V.period} · review-derived controlled record`,body,`<button class="btn" data-action="close-overlays">Close</button><button class="btn primary" onclick="window.print()">Print / PDF</button>`,'xl')}
  function openReview(){const r=currentReview();state.selectedReview=r.id;__setPm22Page('reviews');render()}
  function syncReview(){const r=currentReview(),k=keyFor(r.id,V.period),p=V.products[k]||{};p.sourceSignature='';V.products[k]=p;syncReviewProducts();historyAdd(r.id,'Manual review-to-scorecard synchronization completed.');save();render();if(typeof toast==='function')toast('Review synchronized',`${r.name}'s current review outcome, ratings and narrative are reflected in the scorecard.`)}
  function decorateReviewScorecardLink(){
    if(state.page!=='reviews')return;const r=(state.reviews||[]).find(x=>x.id===state.selectedReview)||(state.reviews||[])[0];if(!r)return;const toolbar=document.querySelector('#workspace .v13-review-layout main .v13-card-head .v13-toolbar')||document.querySelector('#workspace .v13-review-layout main .v13-card-head');if(!toolbar||toolbar.querySelector('[data-v18-action=\"open-review-scorecard\"]'))return;const b=document.createElement('button');b.className='btn small';b.dataset.v18Action='open-review-scorecard';b.dataset.id=r.id;b.innerHTML=`${ico('chart')}${['Completed','Calibrated'].includes(r.status)?'Open generated scorecard':'Open working scorecard'}`;toolbar.appendChild(b)
  }
  function ensureChartTitles(){
    const page=state.page||'dashboard';const fallbacks={dashboard:'Enterprise Performance Trend — Actual vs Target',strategy:'Strategy Execution Trend — Actual vs Target',scorecards:'Scorecard Performance Trajectory — Actual vs Target',objectives:'KPI Attainment Trend — Actual vs Target',kpiAnalytics:'KPI Performance Trend — Actual vs Target',corrective:'Corrective Action Recovery Trend',reviews:'Performance Review Completion Trend',performanceReports:'Performance Reporting Trend',reports:'Performance Reporting Trend',timesheets:'Time Allocation Trend'};
    const selectors=['.v8-big-chart','.sc82-chart','.v11-strategy-pulse','.chart','.v10-room-chart','.v5-chart'];
    document.querySelectorAll(selectors.join(',')).forEach((c,i)=>{if(c.dataset.v18Title)return;const card=c.closest('.v8-card,.sc82-card,.card,.v11-st-card,.enterprise-section,.panel-v6'),head=card?.querySelector('.v8-card-head h3,.sc82-card-head h3,.card-head h3,.v11-st-head h3,h3');let title=(head?.textContent||'').trim();if(!title||/analysis canvas|chart|overview/i.test(title))title=fallbacks[page]||'Performance Trend — Actual vs Target';const sub=/trajectory|trend|performance|score|attainment|recovery/i.test(title)?'Reporting period · percentage / governed score':'Reporting period · governed measure';const label=document.createElement('div');label.className='v18-chart-heading';label.innerHTML=`<strong>${h(title)}</strong><span>${h(sub)}</span>`;c.before(label);c.dataset.v18Title='1';const svg=c.matches('svg')?c:c.querySelector('svg');if(svg){svg.setAttribute('role','img');svg.setAttribute('aria-label',title);if(!svg.querySelector(':scope > title')){const t=document.createElementNS('http://www.w3.org/2000/svg','title');t.textContent=title;svg.prepend(t)}}});
  }
