(()=>{
 'use strict';
 const STORE='matanho.performance.v19.keyResults';
 const DATA=[
  {objective:'Drive sustainable revenue growth',owner:'Rumbidzai Chaza',role:'Chief Commercial Officer',due:'30 Sep 2026',items:[
   {name:'Increase recurring revenue to $4.5M ARR',progress:82,current:'$3.69M',target:'$4.50M',unit:'ARR',source:'ERP + CRM',frequency:'Monthly',evidence:'Revenue ledger + CRM pipeline reconciliation',work:'Enterprise Growth Campaign · Pricing Optimisation'},
   {name:'Acquire 120 new enterprise customers',progress:65,current:'78',target:'120',unit:'Customers',source:'CRM',frequency:'Weekly',evidence:'Approved customer register + signed contracts',work:'Enterprise Growth Campaign · Channel Partner Expansion'},
   {name:'Achieve Net Revenue Retention of 115%',progress:88,current:'112%',target:'115%',unit:'Percent',source:'Billing + CRM',frequency:'Monthly',evidence:'Cohort retention schedule + billing reconciliation',work:'Client Retention Programme · Account Reviews'}]},
  {objective:'Deliver world-class customer experience',owner:'Kudakwashe Biti',role:'Head of Customer Success',due:'30 Sep 2026',items:[
   {name:'Improve CSAT score to 4.6/5',progress:72,current:'4.2',target:'4.6',unit:'Score / 5',source:'Customer Survey Platform',frequency:'Monthly',evidence:'Survey response dataset + QA report',work:'Voice of Customer · Service Recovery'},
   {name:'Reduce response time to <2h',progress:58,current:'2.8h',target:'2h',unit:'Hours',source:'Service Desk',frequency:'Daily',evidence:'Service desk response-time extract',work:'Support Workflow Redesign · Capacity Plan'},
   {name:'Achieve 95% SLA compliance',progress:46,current:'88%',target:'95%',unit:'Percent',source:'Service Desk',frequency:'Weekly',evidence:'SLA exception register + service report',work:'SLA Recovery Plan · Escalation Automation'}]},
  {objective:'Build high-performing, engaged teams',owner:'Tatenda Mlambo',role:'Head of People & Culture',due:'30 Sep 2026',items:[
   {name:'Increase engagement score to 80%',progress:87,current:'78%',target:'80%',unit:'Percent',source:'Engagement Survey',frequency:'Quarterly',evidence:'Survey dataset + response-quality report',work:'Engagement Action Plan · Manager Enablement'},
   {name:'Increase training completion to 95%',progress:79,current:'88%',target:'95%',unit:'Percent',source:'LMS',frequency:'Monthly',evidence:'LMS completion report + attendance evidence',work:'Leadership Academy · Mandatory Learning'},
   {name:'Improve succession coverage',progress:86,current:'81%',target:'90%',unit:'Percent',source:'HRIS',frequency:'Monthly',evidence:'Succession slate + talent review approvals',work:'Talent Review Cycle · Critical Role Planning'}]}
 ];
 let saved={}; try{saved=JSON.parse(localStorage.getItem(STORE)||'{}')||{}}catch(_){saved={}}
 const esc19=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
 const key=(oi,ki)=>`${oi}:${ki}`;
 const objectiveIndex=()=>Math.max(0,Math.min(DATA.length-1,Number(state.v6Layer?.id)||0));
 function record(oi,ki){const base=DATA[oi]?.items[ki]||DATA[0].items[0],change=saved[key(oi,ki)]||{};return {...base,...change,history:Array.isArray(change.history)?change.history:[]}}
 function statusFor(p){return Number(p)<60?'Needs attention':Number(p)<75?'Watch':'On track'}
 function pill(p){return `<span class="v19-kr-pill ${Number(p)<75?'watch':''}">${esc19(statusFor(p))}</span>`}
 function stripGeneric(){document.querySelectorAll('#modalLayer .zoom-insight-v6,#drawer .zoom-insight-v6').forEach(n=>n.remove())}
 const modalBase=window.modal;
 if(typeof modalBase==='function')window.modal=function(){const out=modalBase.apply(this,arguments);stripGeneric();return out};
 const drawerBase=window.openDrawer;
 if(typeof drawerBase==='function')window.openDrawer=function(){const out=drawerBase.apply(this,arguments);stripGeneric();return out};
 const observer=new MutationObserver(stripGeneric);observer.observe(document.body,{subtree:true,childList:true});
 function historyRows(r){const custom=r.history||[];const rows=custom.length?custom:[
   {date:'10 Aug 2026',text:`Current result confirmed at ${r.current}.`,actor:'Owner check-in'},
   {date:'08 Aug 2026',text:'Evidence source reconciled and validated.',actor:'System control'},
   {date:'04 Aug 2026',text:'Manager reviewed progress against approved target.',actor:'Manager review'}
  ];return rows.slice(0,5).map(x=>`<div class="v19-kr-history-row"><time>${esc19(x.date)}</time><strong>${esc19(x.text)}</strong><span>${esc19(x.actor)}</span></div>`).join('')}
 function openKR(ki){const oi=objectiveIndex(),o=DATA[oi],r=record(oi,ki),code=`OBJ-${String(oi+1).padStart(2,'0')} · KR-${String(ki+1).padStart(2,'0')}`;const body=`<div class="v19-kr-shell"><section class="v19-kr-hero"><div><span class="v19-kr-kicker">${esc19(code)} · ${esc19(o.objective)}</span><h3>${esc19(r.name)}</h3><p>This record shows the governed result, approved target, source evidence, ownership and update history for the selected key result.</p><div class="v19-kr-owner">${typeof profilePhoto==='function'?profilePhoto(o.owner,'sm'):''}<div><strong style="font-size:9px;font-weight:500">${esc19(o.owner)}</strong><div style="font-size:8px;color:#788499">${esc19(o.role)} · accountable owner</div></div></div></div><div class="v19-kr-score"><strong>${Math.round(Number(r.progress)||0)}%</strong><span>Attainment</span><div class="v19-kr-progress"><i style="width:${Math.max(0,Math.min(100,Number(r.progress)||0))}%"></i></div><div style="margin-top:8px">${pill(r.progress)}</div></div></section><div class="v19-kr-metrics"><div class="v19-kr-metric"><span>Current result</span><strong>${esc19(r.current)}</strong><small>${esc19(r.unit)}</small></div><div class="v19-kr-metric"><span>Approved target</span><strong>${esc19(r.target)}</strong><small>Due ${esc19(o.due)}</small></div><div class="v19-kr-metric"><span>Update frequency</span><strong>${esc19(r.frequency)}</strong><small>Governed cadence</small></div><div class="v19-kr-metric"><span>Evidence status</span><strong>Current</strong><small>${esc19(r.source)}</small></div></div><div class="v19-kr-grid"><section class="v19-kr-card"><header><div><h4>Result definition & control record</h4><p>The measurement specification behind this key result.</p></div>${pill(r.progress)}</header><div class="v19-kr-body"><div class="v19-kr-record"><span>Objective</span><strong>${esc19(o.objective)}</strong><span>Key result</span><strong>${esc19(r.name)}</strong><span>Measure</span><strong>${esc19(r.unit)}</strong><span>Source system</span><strong>${esc19(r.source)}</strong><span>Evidence basis</span><strong>${esc19(r.evidence)}</strong><span>Linked delivery</span><strong>${esc19(r.work)}</strong><span>Accountable owner</span><strong>${esc19(o.owner)}</strong><span>Review due</span><strong>${esc19(o.due)}</strong></div><div class="v19-kr-note" style="margin-top:10px">Progress is reported against the approved target and should be updated only from the named source or through a documented manager-approved override.</div></div></section><section class="v19-kr-card"><header><div><h4>Record history</h4><p>Latest material updates to this result.</p></div><span class="v19-kr-kicker">Audit retained</span></header><div class="v19-kr-body"><div class="v19-kr-history">${historyRows(r)}</div></div></section></div><div class="v19-kr-grid"><section class="v19-kr-card"><header><div><h4>Evidence & linked work</h4><p>What substantiates the result and what is driving it.</p></div></header><div class="v19-kr-body v19-kr-list"><div class="v19-kr-list-item"><i>EV</i><div><strong>${esc19(r.evidence)}</strong><span>${esc19(r.source)} · validated source</span></div><b>Current</b></div><div class="v19-kr-list-item"><i>WK</i><div><strong>${esc19(r.work)}</strong><span>Projects and tasks linked to the result</span></div><b>Active</b></div></div></section><section class="v19-kr-card"><header><div><h4>Management actions</h4><p>Update the record or continue into the related workflow.</p></div></header><div class="v19-kr-body"><div class="v19-kr-actions"><button class="btn primary" data-v19-kr-action="update" data-kr="${ki}">Update result</button><button class="btn" data-v19-kr-action="evidence" data-kr="${ki}">Add evidence note</button><button class="btn" data-v19-kr-action="work" data-kr="${ki}">Open linked work</button></div></div></section></div></div>`;modal('Key result intelligence',`${code} · governed outcome record`,body,'<button class="btn" data-action="close-overlays">Close</button>','xl');stripGeneric()}
 function updateModal(ki){const oi=objectiveIndex(),o=DATA[oi],r=record(oi,ki);const body=`<form id="v19KRUpdate" class="v19-kr-form"><input type="hidden" name="oi" value="${oi}"><input type="hidden" name="ki" value="${ki}"><div class="v19-kr-field full"><label>Key result</label><input value="${esc19(r.name)}" disabled></div><div class="v19-kr-field"><label>Current result</label><input name="current" required value="${esc19(r.current)}"></div><div class="v19-kr-field"><label>Attainment / progress (%)</label><input name="progress" type="number" min="0" max="100" step="1" required value="${Math.round(Number(r.progress)||0)}"></div><div class="v19-kr-field"><label>Approved target</label><input name="target" required value="${esc19(r.target)}"></div><div class="v19-kr-field"><label>Source system</label><input name="source" required value="${esc19(r.source)}"></div><div class="v19-kr-field full"><label>Update note / evidence reference</label><textarea name="note" required placeholder="State what changed, why, and the supporting evidence."></textarea></div></form>`;modal('Update key result',`${esc19(o.objective)} · controlled update`,body,`<button class="btn" data-v19-kr-action="cancel" data-kr="${ki}">Cancel</button><button class="btn primary" data-v19-kr-action="save" data-kr="${ki}">Save update</button>`);stripGeneric()}
 function evidenceModal(ki){const oi=objectiveIndex(),r=record(oi,ki);const body=`<form id="v19KREvidence" class="v19-kr-form"><input type="hidden" name="oi" value="${oi}"><input type="hidden" name="ki" value="${ki}"><div class="v19-kr-field full"><label>Evidence / source note</label><textarea name="note" required placeholder="Reference the document, system extract, approval, check-in or reconciliation that supports ${esc19(r.name)}."></textarea></div><div class="v19-kr-field"><label>Evidence status</label><select name="status"><option>Validated</option><option>Pending validation</option><option>Manager confirmed</option></select></div><div class="v19-kr-field"><label>Effective date</label><input name="date" type="date" value="2026-08-11"></div></form>`;modal('Add key result evidence',r.name,body,`<button class="btn" data-v19-kr-action="cancel" data-kr="${ki}">Cancel</button><button class="btn primary" data-v19-kr-action="evidence-save" data-kr="${ki}">Add evidence</button>`);stripGeneric()}
 function persist(oi,ki,patch,historyText,actor='Manager update'){const k=key(oi,ki),old=saved[k]||{};saved[k]={...old,...patch,history:[{date:'11 Aug 2026',text:historyText,actor},...(old.history||[])]};localStorage.setItem(STORE,JSON.stringify(saved))}
 function saveUpdate(){const f=document.getElementById('v19KRUpdate');if(!f?.reportValidity())return;const d=new FormData(f),oi=Number(d.get('oi')),ki=Number(d.get('ki')),current=String(d.get('current')||''),target=String(d.get('target')||''),source=String(d.get('source')||''),progress=Math.max(0,Math.min(100,Number(d.get('progress'))||0)),note=String(d.get('note')||'');persist(oi,ki,{current,target,source,progress},`${note} Current result ${current}; attainment ${progress}%.`,state.role||'Manager');decorateRows();openKR(ki);if(typeof toast==='function')toast('Key result updated','The governed result and audit history were updated.')}
 function saveEvidence(){const f=document.getElementById('v19KREvidence');if(!f?.reportValidity())return;const d=new FormData(f),oi=Number(d.get('oi')),ki=Number(d.get('ki')),note=String(d.get('note')||''),status=String(d.get('status')||'Validated');persist(oi,ki,{},`${status}: ${note}`,state.role||'Manager');openKR(ki);if(typeof toast==='function')toast('Evidence recorded','The evidence note was added to the key result history.')}
 function decorateRows(){if(state.page!=='objectives'||state.v6Layer?.type!=='objective')return;const oi=objectiveIndex();document.querySelectorAll('.kr-row-v6[data-v6-kr]').forEach(row=>{const ki=Number(row.dataset.v6Kr),r=record(oi,ki),cells=row.children;if(cells[2]){const s=cells[2].querySelector('strong');if(s)s.textContent=`${Math.round(Number(r.progress)||0)}%`;const bar=cells[2].querySelector('.progress i');if(bar)bar.style.width=`${Math.max(0,Math.min(100,Number(r.progress)||0))}%`}if(cells[3]){const vals=cells[3].querySelectorAll('strong,.micro');const strong=cells[3].querySelector('strong');if(strong)strong.textContent=r.current;const micros=cells[3].querySelectorAll('.micro');if(micros[1])micros[1].textContent=` / ${r.target}`}if(cells[4])cells[4].innerHTML=typeof badge==='function'?badge(statusFor(r.progress)):pill(r.progress)})}
 const renderBase=window.render;if(typeof renderBase==='function')window.render=function(){const out=renderBase.apply(this,arguments);requestAnimationFrame(()=>{decorateRows();stripGeneric()});return out};
 document.addEventListener('click',e=>{const kr=e.target.closest('[data-v6-kr]');if(kr&&state.page==='objectives'&&state.v6Layer?.type==='objective'){e.preventDefault();e.stopImmediatePropagation();openKR(Number(kr.dataset.v6Kr)||0);return}const a=e.target.closest('[data-v19-kr-action]');if(!a)return;e.preventDefault();e.stopImmediatePropagation();const act=a.dataset.v19KrAction,ki=Number(a.dataset.kr)||0;if(act==='update'){updateModal(ki);return}if(act==='evidence'){evidenceModal(ki);return}if(act==='save'){saveUpdate();return}if(act==='evidence-save'){saveEvidence();return}if(act==='cancel'){openKR(ki);return}if(act==='work'){if(typeof closeOverlays==='function')closeOverlays();__setPm22Page('tasks');state.v6Layer=null;if(typeof render==='function')render();if(typeof toast==='function')toast('Linked work opened','Tasks & Projects now shows the delivery workspace linked to this result.');return}},true);
 requestAnimationFrame(()=>{decorateRows();stripGeneric()});
 window.MatanhoV19KeyResults=Object.freeze({version:'19.0.0',open:(objective=0,kr=0)=>{__setPm22Page('objectives');state.v6Layer={type:'objective',id:String(objective)};if(typeof render==='function')render();setTimeout(()=>openKR(kr),0)},data:()=>JSON.parse(JSON.stringify(saved))});
})();

;

