 const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(V))}catch(_){}};
 const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
 const photo=(n,size='sm')=>typeof profilePhoto==='function'?profilePhoto(n,size):(window.MatanhoProfilePhoto?window.MatanhoProfilePhoto(n,size):`<span class="person-avatar">${h(String(n||'U').split(/\s+/).map(x=>x[0]).slice(0,2).join(''))}</span>`);
 const status=(s)=>`<span class="v20-status ${h(String(s||'').toLowerCase().replace(/\s+/g,'-'))}">${h(s)}</span>`;
